import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const assetLocale = (locale) => locale === 'zh_Hans' ? 'zh-hans' : locale;

const pages = {
  de: {
    trainingPlanning: {
      title: 'Trainingsplanung – Kaderblick-Dokumentation',
      heading: 'Training planen und durchführen',
      lead: 'Vom Kalendertermin über den Ablaufplan bis zur mobilen Durchführung und Nachbereitung.',
      body: `<h2>Planung am Trainingstermin öffnen</h2><p>Die Trainingsplanung ergänzt den vorhandenen Kalendertermin. Öffne ein Training im <strong>Kalender</strong> und wähle <strong>Training planen</strong> oder <strong>Planung öffnen</strong>. Alternativ bündelt <strong>Trainings</strong> die planbaren und bereits geplanten Einheiten deiner ausgewählten Mannschaft.</p><p>Im Kopf stehen Mannschaft, Datum, Uhrzeit und Spielstätte. Prüfe diesen Kontext vor jeder Änderung. Die Aktion erscheint nur, wenn du das konkrete Training bearbeiten darfst.</p><figure class="screenshot"><img src="/images/docs/de/training-planning/overview.png" alt="Trainingsübersicht mit planbaren und vorbereiteten Einheiten" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Die Übersicht führt zur Planung eines vorhandenen Kalendertermins und erzeugt keinen zweiten Termin.</figcaption></figure><h2>Entwurf erstellen</h2><ol><li>Trage <strong>Schwerpunkt</strong> und bei Bedarf ein genaueres Ziel ein.</li><li>Füge Ablaufblöcke mit Titel, Dauer und Anleitung hinzu.</li><li>Dupliziere, lösche oder verschiebe Blöcke mit den sichtbaren Aktionen. Ziehen ist nicht die einzige Möglichkeit zum Sortieren.</li><li>Ergänze Material und Mengen im eigenen Materialbereich.</li><li>Vergleiche die Gesamtdauer mit der Dauer des Kalendertermins.</li><li>Wähle <strong>Entwurf speichern</strong>. Ein Entwurf darf noch unvollständig sein.</li></ol><figure class="screenshot"><img src="/images/docs/de/training-planning/editor.png" alt="Editor einer Trainingsplanung mit Ablaufblöcken, Dauer und Material" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Ablauf, Dauer und Material werden in einem zusammenhängenden Arbeitsbereich gepflegt.</figcaption></figure><h2>Vorlagen verwenden</h2><p>Eine Mannschaftsvorlage kopiert ihren Ablauf und das Material in das ausgewählte Training. Danach ist die neue Planung unabhängig: Änderungen wirken weder auf die Vorlage noch auf andere Trainings. Du kannst eine geeignete Planung als neue Vorlage speichern sowie vorhandene Vorlagen umbenennen oder archivieren, wenn dir diese Aktionen angeboten werden.</p><h2>Einheit vorbereiten und durchführen</h2><p>Bevor eine Einheit als bereit markiert wird, benötigt sie einen Schwerpunkt und mindestens einen Ablaufblock. Weicht die geplante Gesamtdauer von der Terminlänge ab, zeigt Kaderblick die Differenz und verlangt vor der Freigabe eine bewusste Bestätigung.</p><ol><li>Öffne am Training <strong>Durchführen</strong>.</li><li>Arbeite die Blöcke in der vorgesehenen Reihenfolge ab.</li><li>Markiere erledigte Blöcke und ergänze bei Bedarf eine kurze Abweichungsnotiz.</li><li>Nutze <strong>Vorheriger</strong> und <strong>Nächster</strong>; der Fortschritt bleibt nach dem Neuladen erhalten.</li><li>Schließe die Einheit bewusst ab und erfasse die interne Nachbereitung.</li></ol><figure class="screenshot"><img src="/images/docs/de/training-planning/run-mobile.png" alt="Mobile Durchführung einer Trainingseinheit" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Auf dem Smartphone stehen aktueller Block, Zeit, Anleitung und Fortschritt im Mittelpunkt.</figcaption></figure><h2>Abschluss und Wiederöffnung</h2><p>Die Zusammenfassung unterscheidet geplante, durchgeführte und ausgelassene Blöcke. Eine abgeschlossene Einheit kann nach einer Bestätigung wieder geöffnet werden. Verwende <strong>Als Vorlage speichern</strong>, wenn der Ablauf künftig erneut genutzt werden soll.</p><h2>Probleme lösen</h2><ul><li><strong>Planung fehlt:</strong> Prüfe Mannschaft, Terminart und dein Bearbeitungsrecht am Training.</li><li><strong>Änderungskonflikt:</strong> Lade den aktuellen Stand und übernimm deine Änderung anschließend bewusst erneut; Kaderblick überschreibt keine zwischenzeitliche Bearbeitung still.</li><li><strong>Termin abgesagt oder gelöscht:</strong> Öffne den Kalender und prüfe den aktuellen Terminstatus.</li><li><strong>Vorlage fehlt:</strong> Vorlagen gehören zur berechtigten Mannschaft und Sportart; archivierte Vorlagen werden nicht regulär angeboten.</li></ul>`,
    },
    locationOccupancy: {
      title: 'Platzbelegung – Kaderblick-Dokumentation', heading: 'Platzbelegung prüfen', lead: 'Spiele, Trainings und weitere Termine nach Spielstätte und Zeitraum vergleichen.',
      body: `<h2>Belegung öffnen und eingrenzen</h2><p>Öffne <strong>Platzbelegung</strong>. Wähle Wochen- oder Saisonansicht, die gewünschte Belegungsart und die Spielstätten. In der Wochenansicht lassen sich bis zu vier Sportflächen gleichzeitig vergleichen.</p><figure class="screenshot"><img src="/images/docs/de/location-occupancy/overview.png" alt="Wochenansicht der Platzbelegung mit mehreren Terminen" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Freie Tage und vorhandene Belegungen sind nach Datum, Uhrzeit und Spielstätte geordnet.</figcaption></figure><h2>Einträge verstehen</h2><p>Jede Belegung nennt Zeit, Termin, Mannschaft, Terminart und den hinterlegten Platzbereich. Öffne einen Eintrag, um den zugehörigen Kalendertermin zu prüfen oder – mit passender Berechtigung – zu bearbeiten.</p><h2>Zeitraum und Ausdruck verwenden</h2><p><strong>Aktuelle Woche</strong> springt zum heutigen Zeitraum zurück. Mit der Datumsnavigation wechselst du vor und zurück. <strong>Übersicht drucken</strong> erstellt eine für Aushang oder Abstimmung geeignete Ansicht des aktuell gewählten Zeitraums und der gewählten Spielstätten.</p><h2>Fehlende oder widersprüchliche Belegungen</h2><p>Die Platzbelegung verwendet die vorhandenen Kalendertermine. Prüfe bei einem fehlenden Eintrag Terminart, Datum, Spielstätte und Platzbereich im Kalender. Lege keinen zweiten Termin nur für die Belegungsansicht an.</p>`,
    },
    memberPortal: {
      title: 'Mitgliederportal und Mitgliedsantrag – Kaderblick-Dokumentation', heading: 'Mitgliedschaft und eigene Vereinsdaten', lead: 'Mitgliedschaft beantragen, verknüpfte Mitgliedsakten einsehen und Änderungen nachvollziehbar einreichen.',
      body: `<h2>Mitgliedschaft beantragen</h2><p>Wenn noch keine zugängliche Mitgliedschaft besteht, zeigt die Navigation <strong>Mitglied werden</strong>. Wähle den Verein, lies die bereitgestellte Satzung und öffne <strong>Aufnahmeantrag stellen</strong>. Eine Mitgliedschaft entsteht erst nach der Annahme durch den Verein.</p><ol><li>Prüfe Verein und Satzungsstand.</li><li>Erfasse die verlangten persönlichen und mitgliedschaftsbezogenen Angaben.</li><li>Füge nur die angeforderten Nachweise hinzu.</li><li>Prüfe die Zusammenfassung und sende den Antrag.</li><li>Verfolge Status, Rückfragen und Antworten am Antrag.</li></ol><figure class="screenshot"><img src="/images/docs/de/member-portal/application.png" alt="Auswahl eines Vereins für einen Mitgliedsantrag" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Verein und Satzung werden vor dem Öffnen des Antrags eindeutig angezeigt.</figcaption></figure><h2>Mitgliederportal öffnen</h2><p>Nach einer bestätigten Verknüpfung erscheint <strong>Mitgliederportal</strong>. Bei mehreren Beziehungen wählst du zuerst die richtige Person und den richtigen Verein. Die Übersicht trennt Profil, Finanzen, Dokumente und Änderungsanträge.</p><figure class="screenshot"><img src="/images/docs/de/member-portal/overview.png" alt="Mitgliederportal mit Auswahl der Mitgliedsbeziehung" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Der ausgewählte Vereins- und Personenkontext gilt für alle angezeigten Daten und Aktionen.</figcaption></figure><h2>Änderung einreichen</h2><p>Öffne <strong>Änderungen</strong>, prüfe den aktuellen Stand und ändere nur tatsächlich veraltete Angaben. Nach dem Absenden bleibt der Antrag bis zur Bearbeitung nachvollziehbar. Du kannst einen noch zulässigen Antrag zurückziehen, korrigieren und erneut einreichen. Rückfragen der Vereinsverwaltung und deine Antworten bleiben im Verlauf erhalten.</p><h2>Finanzen und Dokumente</h2><p>Unter <strong>Finanzen</strong> siehst du die für diese Mitgliedsbeziehung freigegebenen Forderungen, Zahlungen und Mandatsangaben. Unter <strong>Dokumente</strong> kannst du bereitgestellte endgültige Dokumente herunterladen. Ein leerer Bereich bedeutet nicht automatisch einen Ladefehler; während des Ladens zeigt Kaderblick einen eigenen Status.</p><h2>Verknüpfung statt Mitgliedschaft</h2><p>Eine Konto-, Spieler- oder Trainerverknüpfung ersetzt keine Vereinsmitgliedschaft. Fehlt eine vorhandene Mitgliedschaft im Portal, nutze die Verknüpfungsanfrage im Profil oder wende dich an die Vereinsverwaltung. Prüfe bei mehreren Personen stets den ausgewählten Kontext.</p>`,
    },
  },
  en: {
    trainingPlanning: { title: 'Training planning – Kaderblick documentation', heading: 'Plan and run training', lead: 'From the calendar event to the session plan, mobile delivery and review.', body: `<h2>Open planning from a training event</h2><p>Training planning extends the existing calendar event. Open a training in <strong>Calendar</strong> and select <strong>Plan training</strong> or <strong>Open plan</strong>. <strong>Trainings</strong> also lists sessions you may plan for the selected team.</p><p>The header always shows team, date, time and venue. Check this context before editing. The action is only available when you may edit that event.</p><figure class="screenshot"><img src="/images/docs/en/training-planning/overview.png" alt="Training overview with sessions that can be planned" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">The overview opens planning for an existing calendar event; it does not create a second event.</figcaption></figure><h2>Create a draft</h2><ol><li>Enter a focus and, if useful, a more precise objective.</li><li>Add blocks with title, duration and instructions.</li><li>Duplicate, remove or reorder blocks with the visible actions.</li><li>Add equipment and quantities in the equipment section.</li><li>Compare total planned time with the calendar event duration.</li><li>Select <strong>Save draft</strong>; a draft may still be incomplete.</li></ol><figure class="screenshot"><img src="/images/docs/en/training-planning/editor.png" alt="Training plan editor with blocks, duration and equipment" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Sequence, duration and equipment are maintained in one workspace.</figcaption></figure><h2>Use templates</h2><p>A team template copies its sequence and equipment into the selected session. The copy is independent: later changes do not affect the template or other sessions. Available actions let you save a plan as a template, rename templates or archive them.</p><h2>Prepare and run the session</h2><p>A focus and at least one block are required before marking a session ready. When planned time differs from the event duration, Kaderblick shows the difference and requests confirmation.</p><ol><li>Open <strong>Run</strong> on the training.</li><li>Work through the blocks in order.</li><li>Mark completed blocks and add a short deviation note if needed.</li><li>Use Previous and Next; progress remains after reloading.</li><li>Complete the session deliberately and add the internal review.</li></ol><figure class="screenshot"><img src="/images/docs/en/training-planning/run-mobile.png" alt="Mobile delivery of a training session" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">On a phone, the current block, time, instructions and progress take priority.</figcaption></figure><h2>Complete, reopen and troubleshoot</h2><p>The summary separates planned, completed and skipped blocks. A completed session can be reopened after confirmation and saved as a reusable template.</p><ul><li>If a plan is missing, check team, event type and your edit permission.</li><li>For a version conflict, load the current state and reapply the change deliberately.</li><li>For cancelled or deleted events, check the calendar status.</li><li>Templates belong to an authorised team and sport; archived templates are not offered normally.</li></ul>` },
    locationOccupancy: { title: 'Venue occupancy – Kaderblick documentation', heading: 'Review venue occupancy', lead: 'Compare matches, trainings and other events by venue and period.', body: `<h2>Filter occupancy</h2><p>Open <strong>Venue occupancy</strong>. Choose week or season view, the occupancy type and the venues. The week view compares up to four playing areas.</p><figure class="screenshot"><img src="/images/docs/en/location-occupancy/overview.png" alt="Weekly venue occupancy with several events" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Free days and bookings are ordered by date, time and venue.</figcaption></figure><h2>Understand and use entries</h2><p>Each booking shows time, event, team, event type and playing area. Open it to review the calendar event or edit it when authorised. <strong>Current week</strong> returns to today; date controls move through time. <strong>Print overview</strong> prints the selected period and venues.</p><h2>Resolve missing entries</h2><p>The view uses existing calendar events. Check event type, date, venue and playing area in the calendar. Do not create a duplicate event only for occupancy.</p>` },
    memberPortal: { title: 'Member portal and application – Kaderblick documentation', heading: 'Membership and your club data', lead: 'Apply for membership, review linked member records and submit traceable changes.', body: `<h2>Apply for membership</h2><p>If no accessible membership exists, navigation shows <strong>Become a member</strong>. Choose the club, read its statutes and open the application. Membership starts only after approval.</p><ol><li>Check club and statute version.</li><li>Enter the requested personal and membership data.</li><li>Add only requested evidence.</li><li>Review and submit.</li><li>Follow status, questions and replies on the application.</li></ol><figure class="screenshot"><img src="/images/docs/en/member-portal/application.png" alt="Choosing a club for a membership application" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Club and statute version are shown before the form opens.</figcaption></figure><h2>Use the member portal</h2><p>After a confirmed link, <strong>Member portal</strong> appears. If several relationships exist, select the correct person and club first. The overview separates profile, finances, documents and change requests.</p><figure class="screenshot"><img src="/images/docs/en/member-portal/overview.png" alt="Member portal with membership relationship selection" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">The selected club and person context applies to all displayed data and actions.</figcaption></figure><h2>Submit and correct changes</h2><p>Open Changes, compare the current state and change only outdated information. Submitted requests keep their status and history. Where allowed, withdraw, correct and resubmit a request. Questions from club management and your replies remain in the history.</p><h2>Finances, documents and links</h2><p>Finances shows released receivables, payments and mandate data for this relationship. Documents provides final documents for download. An account, player or coach link does not itself create membership. If an existing membership is missing, request the link from the profile or contact club management.</p>` },
  },
  fr: {
    trainingPlanning: { title: 'Planification des entraînements – Documentation Kaderblick', heading: 'Planifier et réaliser un entraînement', lead: 'Du rendez-vous du calendrier au déroulement mobile et au bilan.', body: `<h2>Ouvrir la planification depuis l’entraînement</h2><p>La planification complète le rendez-vous existant du calendrier. Ouvre un entraînement puis choisis <strong>Planifier l’entraînement</strong> ou <strong>Ouvrir la planification</strong>. La rubrique <strong>Entraînements</strong> regroupe aussi les séances que tu peux planifier pour l’équipe sélectionnée.</p><p>L’en-tête indique toujours l’équipe, la date, l’heure et le lieu. Vérifie ce contexte avant toute modification.</p><figure class="screenshot"><img src="/images/docs/fr/training-planning/overview.png" alt="Vue des entraînements à planifier" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">La vue ouvre la planification d’un rendez-vous existant sans créer un second rendez-vous.</figcaption></figure><h2>Créer un brouillon</h2><ol><li>Indique le thème principal et, si nécessaire, un objectif précis.</li><li>Ajoute des blocs avec titre, durée et consignes.</li><li>Duplique, supprime ou déplace les blocs avec les actions visibles.</li><li>Ajoute le matériel et les quantités.</li><li>Compare la durée totale avec celle du rendez-vous.</li><li>Enregistre le brouillon, même s’il est encore incomplet.</li></ol><figure class="screenshot"><img src="/images/docs/fr/training-planning/editor.png" alt="Éditeur avec blocs, durée et matériel" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Déroulement, durée et matériel sont réunis dans un même espace.</figcaption></figure><h2>Utiliser des modèles</h2><p>Un modèle d’équipe copie son déroulement et son matériel dans la séance. La copie devient indépendante et ne modifie ni le modèle ni les autres séances.</p><h2>Préparer et réaliser la séance</h2><p>Un thème et au moins un bloc sont requis pour marquer la séance comme prête. Kaderblick signale toute différence avec la durée du rendez-vous.</p><ol><li>Ouvre <strong>Réaliser</strong>.</li><li>Suis les blocs dans l’ordre.</li><li>Marque les blocs réalisés et ajoute une courte note d’écart si nécessaire.</li><li>Utilise Précédent et Suivant ; la progression résiste au rechargement.</li><li>Termine volontairement la séance et complète le bilan interne.</li></ol><figure class="screenshot"><img src="/images/docs/fr/training-planning/run-mobile.png" alt="Réalisation mobile d’un entraînement" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Sur téléphone, le bloc actuel, le temps, les consignes et la progression restent prioritaires.</figcaption></figure><h2>Résoudre les problèmes</h2><ul><li>Si la planification manque, vérifie l’équipe, le type de rendez-vous et ton droit de modification.</li><li>En cas de conflit de version, recharge l’état actuel puis réapplique volontairement la modification.</li><li>Vérifie dans le calendrier si le rendez-vous a été annulé ou supprimé.</li><li>Les modèles archivés ou d’une autre équipe ne sont pas proposés normalement.</li></ul>` },
    locationOccupancy: { title: 'Occupation des installations – Documentation Kaderblick', heading: 'Contrôler l’occupation des installations', lead: 'Comparer matchs, entraînements et autres rendez-vous par lieu et période.', body: `<h2>Filtrer l’occupation</h2><p>Ouvre <strong>Occupation des installations</strong>. Choisis la semaine ou la saison, le type d’occupation et les installations. La vue hebdomadaire compare jusqu’à quatre surfaces.</p><figure class="screenshot"><img src="/images/docs/fr/location-occupancy/overview.png" alt="Occupation hebdomadaire avec plusieurs rendez-vous" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Les jours libres et les occupations sont classés par date, heure et installation.</figcaption></figure><h2>Comprendre et utiliser les entrées</h2><p>Chaque entrée indique l’heure, le rendez-vous, l’équipe, le type et la zone. Ouvre-la pour consulter ou, avec le droit nécessaire, modifier le rendez-vous. La semaine actuelle ramène à aujourd’hui et l’impression reprend la période et les lieux sélectionnés.</p><h2>Corriger une entrée manquante</h2><p>La vue utilise les rendez-vous existants. Vérifie dans le calendrier le type, la date, l’installation et la zone. Ne crée pas de doublon uniquement pour l’occupation.</p>` },
    memberPortal: { title: 'Portail des membres et demande – Documentation Kaderblick', heading: 'Adhésion et données du club', lead: 'Demander une adhésion, consulter les dossiers liés et transmettre des corrections traçables.', body: `<h2>Demander une adhésion</h2><p>Si aucune adhésion accessible n’existe, la navigation affiche <strong>Devenir membre</strong>. Choisis le club, lis les statuts puis ouvre le formulaire. L’adhésion ne commence qu’après l’acceptation du club.</p><ol><li>Vérifie le club et la version des statuts.</li><li>Saisis les données demandées.</li><li>Ajoute uniquement les justificatifs requis.</li><li>Contrôle puis envoie.</li><li>Suis le statut, les questions et les réponses dans la demande.</li></ol><figure class="screenshot"><img src="/images/docs/fr/member-portal/application.png" alt="Choix du club pour une demande d’adhésion" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Le club et la version des statuts apparaissent avant l’ouverture du formulaire.</figcaption></figure><h2>Utiliser le portail</h2><p>Après une liaison confirmée, <strong>Portail des membres</strong> apparaît. Avec plusieurs relations, choisis d’abord la bonne personne et le bon club. La vue sépare profil, finances, documents et demandes de modification.</p><figure class="screenshot"><img src="/images/docs/fr/member-portal/overview.png" alt="Portail avec sélection de la relation d’adhésion" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Le contexte de personne et de club sélectionné s’applique à toutes les données.</figcaption></figure><h2>Modifier et corriger</h2><p>Compare l’état actuel et modifie uniquement les informations devenues obsolètes. Une demande envoyée conserve son statut et son historique. Lorsque l’action est disponible, retire-la, corrige-la et renvoie-la. Les questions et réponses restent visibles.</p><h2>Finances, documents et liaison</h2><p>Les finances montrent les créances, paiements et mandats autorisés. Les documents définitifs peuvent être téléchargés. Une liaison de compte, joueur ou entraîneur ne crée pas une adhésion. Si une adhésion existante manque, demande sa liaison depuis le profil ou contacte le club.</p>` },
  },
  ru: {
    trainingPlanning: { title: 'Планирование тренировок — документация Kaderblick', heading: 'Планирование и проведение тренировки', lead: 'От события календаря до мобильного проведения и итогов.', body: `<h2>Открыть план из тренировки</h2><p>План дополняет существующее событие календаря. Открой тренировку и выбери <strong>Запланировать тренировку</strong> или <strong>Открыть план</strong>. Раздел <strong>Тренировки</strong> также показывает доступные для планирования занятия выбранной команды.</p><p>В заголовке всегда указаны команда, дата, время и место. Проверь контекст перед изменениями.</p><figure class="screenshot"><img src="/images/docs/ru/training-planning/overview.png" alt="Обзор тренировок, доступных для планирования" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Обзор открывает план существующего события и не создаёт вторую тренировку.</figcaption></figure><h2>Создать черновик</h2><ol><li>Укажи основную тему и при необходимости точную цель.</li><li>Добавь блоки с названием, длительностью и инструкцией.</li><li>Дублируй, удаляй и меняй порядок видимыми кнопками.</li><li>Добавь инвентарь и количество.</li><li>Сравни общую длительность с календарным событием.</li><li>Сохрани черновик; он может быть неполным.</li></ol><figure class="screenshot"><img src="/images/docs/ru/training-planning/editor.png" alt="Редактор плана с блоками, временем и инвентарём" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Ход занятия, длительность и инвентарь редактируются в одном рабочем разделе.</figcaption></figure><h2>Использовать шаблоны</h2><p>Шаблон команды копирует ход занятия и инвентарь в выбранную тренировку. Копия независима и не изменяет шаблон или другие занятия.</p><h2>Подготовить и провести</h2><p>Для статуса готовности нужны тема и хотя бы один блок. Kaderblick показывает отличие от длительности события и просит подтверждение.</p><ol><li>Открой <strong>Провести</strong>.</li><li>Выполняй блоки по порядку.</li><li>Отмечай выполненное и при необходимости добавляй короткую заметку.</li><li>Используй Назад и Далее; прогресс сохраняется после перезагрузки.</li><li>Осознанно заверши тренировку и добавь внутренние итоги.</li></ol><figure class="screenshot"><img src="/images/docs/ru/training-planning/run-mobile.png" alt="Мобильное проведение тренировки" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">На телефоне в центре внимания текущий блок, время, инструкция и прогресс.</figcaption></figure><h2>Устранить проблемы</h2><ul><li>Если план отсутствует, проверь команду, тип события и право редактирования.</li><li>При конфликте версии загрузи текущие данные и повтори изменение осознанно.</li><li>Проверь в календаре, не отменено ли событие.</li><li>Архивные шаблоны и шаблоны другой команды обычно не предлагаются.</li></ul>` },
    locationOccupancy: { title: 'Занятость площадок — документация Kaderblick', heading: 'Проверка занятости площадок', lead: 'Сравнение матчей, тренировок и других событий по месту и периоду.', body: `<h2>Настроить просмотр</h2><p>Открой <strong>Занятость площадок</strong>. Выбери неделю или сезон, тип занятости и площадки. В недельном виде можно сравнить до четырёх поверхностей.</p><figure class="screenshot"><img src="/images/docs/ru/location-occupancy/overview.png" alt="Недельная занятость площадок с несколькими событиями" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Свободные дни и события упорядочены по дате, времени и месту.</figcaption></figure><h2>Работать с записями</h2><p>Запись показывает время, событие, команду, тип и зону площадки. Открой её для просмотра или редактирования календарного события. Кнопка текущей недели возвращает к сегодняшней дате, а печать использует выбранный период и площадки.</p><h2>Найти пропущенную запись</h2><p>Обзор использует существующие события календаря. Проверь тип, дату, площадку и зону. Не создавай дубликат только для этого обзора.</p>` },
    memberPortal: { title: 'Портал участника и заявление — документация Kaderblick', heading: 'Членство и клубные данные', lead: 'Подать заявление, просматривать связанные записи и отправлять отслеживаемые изменения.', body: `<h2>Подать заявление</h2><p>Если доступного членства нет, навигация показывает <strong>Стать участником</strong>. Выбери клуб, прочитай устав и открой форму. Членство начинается только после одобрения клубом.</p><ol><li>Проверь клуб и версию устава.</li><li>Введи запрошенные данные.</li><li>Добавь только необходимые подтверждения.</li><li>Проверь и отправь заявление.</li><li>Следи за статусом, вопросами и ответами в самом заявлении.</li></ol><figure class="screenshot"><img src="/images/docs/ru/member-portal/application.png" alt="Выбор клуба для заявления" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Клуб и версия устава показаны до открытия формы.</figcaption></figure><h2>Использовать портал</h2><p>После подтверждённой связи появляется <strong>Портал участника</strong>. При нескольких отношениях сначала выбери нужного человека и клуб. Разделы отделяют профиль, финансы, документы и запросы изменений.</p><figure class="screenshot"><img src="/images/docs/ru/member-portal/overview.png" alt="Портал с выбором отношения членства" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Выбранный человек и клуб определяют все показанные данные.</figcaption></figure><h2>Изменить и исправить</h2><p>Сравни текущие данные и меняй только устаревшее. Отправленный запрос сохраняет статус и историю. Если разрешено, его можно отозвать, исправить и отправить снова. Вопросы клуба и ответы остаются в истории.</p><h2>Финансы, документы и связи</h2><p>Финансы показывают разрешённые начисления, платежи и мандаты. Итоговые документы доступны для скачивания. Связь аккаунта, игрока или тренера сама по себе не создаёт членство. Для отсутствующего существующего членства запроси связь в профиле или обратись в клуб.</p>` },
  },
  zh_Hans: {
    trainingPlanning: { title: '训练计划 – Kaderblick 文档', heading: '计划并执行训练', lead: '从日历训练到流程、移动执行和复盘。', body: `<h2>从训练日程打开计划</h2><p>训练计划扩展现有日历日程。打开训练并选择<strong>计划训练</strong>或<strong>打开计划</strong>。<strong>训练</strong>页面也会汇总当前球队中可计划和已有计划的训练。</p><p>页头始终显示球队、日期、时间和场地。修改前请确认这些信息。</p><figure class="screenshot"><img src="/images/docs/zh-hans/training-planning/overview.png" alt="可计划训练的概览" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">概览打开现有日历训练的计划，不会创建第二个日程。</figcaption></figure><h2>创建草稿</h2><ol><li>填写训练重点，必要时补充具体目标。</li><li>添加包含标题、时长和说明的流程区块。</li><li>使用可见操作复制、删除或调整顺序。</li><li>在器材区添加器材和数量。</li><li>比较总时长与日历训练时长。</li><li>选择<strong>保存草稿</strong>；草稿可以暂时不完整。</li></ol><figure class="screenshot"><img src="/images/docs/zh-hans/training-planning/editor.png" alt="含流程区块、时长和器材的训练编辑器" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">流程、时长和器材在同一工作区中维护。</figcaption></figure><h2>使用模板</h2><p>球队模板会把流程和器材复制到所选训练。副本相互独立，之后的修改不会影响模板或其他训练。</p><h2>准备并执行训练</h2><p>标记为已准备前，必须填写重点并至少添加一个区块。若计划时长不同，Kaderblick 会显示差值并要求确认。</p><ol><li>在训练中打开<strong>执行</strong>。</li><li>按顺序完成区块。</li><li>标记已完成区块，必要时记录简短偏差。</li><li>使用上一个和下一个；刷新后进度仍保留。</li><li>明确结束训练并填写内部复盘。</li></ol><figure class="screenshot"><img src="/images/docs/zh-hans/training-planning/run-mobile.png" alt="移动端执行训练" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">手机上重点显示当前区块、时间、说明和进度。</figcaption></figure><h2>解决问题</h2><ul><li>找不到计划时，检查球队、日程类型和编辑权限。</li><li>发生版本冲突时，加载当前状态后再明确应用修改。</li><li>在日历中检查训练是否已取消或删除。</li><li>已归档或其他球队的模板通常不会显示。</li></ul>` },
    locationOccupancy: { title: '场地占用 – Kaderblick 文档', heading: '查看场地占用', lead: '按场地和时间比较比赛、训练及其他日程。', body: `<h2>筛选占用情况</h2><p>打开<strong>场地占用</strong>，选择周视图或赛季视图、占用类型和场地。周视图最多可同时比较四块运动区域。</p><figure class="screenshot"><img src="/images/docs/zh-hans/location-occupancy/overview.png" alt="包含多个日程的每周场地占用" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">空闲日期和占用按日期、时间和场地排列。</figcaption></figure><h2>理解并使用记录</h2><p>每条记录显示时间、日程、球队、类型和场地区域。打开记录可查看日历日程；有权限时也可编辑。当前周可返回今天，打印概览会使用当前所选时间和场地。</p><h2>查找缺失记录</h2><p>本页面使用现有日历日程。请在日历中检查类型、日期、场地和区域，不要只为占用页面创建重复日程。</p>` },
    memberPortal: { title: '会员门户与入会申请 – Kaderblick 文档', heading: '会员资格与俱乐部资料', lead: '申请入会、查看关联会员档案并提交可追踪的修改。', body: `<h2>申请入会</h2><p>如果没有可访问的会员资格，导航会显示<strong>加入会员</strong>。选择俱乐部，阅读章程并打开申请表。只有俱乐部批准后，会员资格才会生效。</p><ol><li>确认俱乐部和章程版本。</li><li>填写所需个人和会员资料。</li><li>只添加要求的证明。</li><li>检查后提交。</li><li>在申请中跟踪状态、问题和回复。</li></ol><figure class="screenshot"><img src="/images/docs/zh-hans/member-portal/application.png" alt="为入会申请选择俱乐部" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">打开表单前会明确显示俱乐部和章程版本。</figcaption></figure><h2>使用会员门户</h2><p>关联确认后会显示<strong>会员门户</strong>。若有多个关系，请先选择正确的人和俱乐部。概览分为资料、财务、文档和修改申请。</p><figure class="screenshot"><img src="/images/docs/zh-hans/member-portal/overview.png" alt="可选择会员关系的会员门户" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">所选人员和俱乐部适用于全部显示数据和操作。</figcaption></figure><h2>提交和更正修改</h2><p>比较当前资料，只修改过时内容。提交后仍可查看状态和历史。在允许时可以撤回、修正并重新提交。俱乐部的问题和你的回复都会保留。</p><h2>财务、文档和关联</h2><p>财务显示该关系获准查看的应收、付款和授权资料；最终文档可下载。账号、球员或教练关联本身不等于会员资格。若现有会员资格缺失，请在个人资料中申请关联或联系俱乐部管理人员。</p>` },
  },
};

function documentFor(page) {
  return {
    title: page.title,
    hero: { heading: page.heading, lead: page.lead, eyebrow: null, chips: [] },
    body: page.body
      .replace(/<figure class="screenshot"><img[^>]+run-mobile\.png[\s\S]*?<\/figure>/, '')
      .replace(/ Alternativ bündelt <strong>Trainings<\/strong> die planbaren und bereits geplanten Einheiten deiner ausgewählten Mannschaft\./, '')
      .replace(/ <strong>Trainings<\/strong> also lists sessions you may plan for the selected team\./, '')
      .replace(/ La rubrique <strong>Entraînements<\/strong> regroupe aussi les séances que tu peux planifier pour l’équipe sélectionnée\./, '')
      .replace(/ Раздел <strong>Тренировки<\/strong> также показывает доступные для планирования занятия выбранной команды\./, '')
      .replace(/<strong>训练<\/strong>页面也会汇总当前球队中可计划和已有计划的训练。/, ''),
  };
}

for (const [locale, localized] of Object.entries(pages)) {
  const target = join(root, 'content', locale);
  await writeFile(join(target, 'training-planning.json'), `${JSON.stringify(documentFor(localized.trainingPlanning), null, 4)}\n`);
  await writeFile(join(target, 'location-occupancy.json'), `${JSON.stringify(documentFor(localized.locationOccupancy), null, 4)}\n`);
  await writeFile(join(target, 'member-portal.json'), `${JSON.stringify(documentFor(localized.memberPortal), null, 4)}\n`);
}

const playerHighlightCorrections = {
  de: ['Über <strong>Highlight teilen</strong> kann eine dafür vorgesehene Spielergrafik erzeugt werden.', '<strong>Highlight teilen</strong> erscheint nur, wenn für die Sportart eine passende Postervorlage verfügbar ist. Dann kannst du daraus eine Spielergrafik erzeugen.'],
  en: ['<strong>Share highlight</strong> can generate the intended player graphic.', '<strong>Share highlight</strong> appears only when a suitable poster template is available for the sport. It can then generate the player graphic.'],
  fr: ['<strong>Partager le highlight</strong> peut générer le visuel prévu pour le joueur.', '<strong>Partager le highlight</strong> apparaît uniquement si un modèle d’affiche adapté au sport est disponible. Tu peux alors générer le visuel du joueur.'],
  ru: ['<strong>Поделиться highlight</strong> создаёт предусмотренную графику игрока.', '<strong>Поделиться highlight</strong> отображается только при наличии подходящего шаблона плаката для этого вида спорта. Тогда можно создать графику игрока.'],
  zh_Hans: ['<strong>分享 Highlight</strong>可生成相应球员图片。', '只有当前运动项目存在合适的海报模板时，才会显示<strong>分享 Highlight</strong>。此时可生成球员图片。'],
};

for (const [locale, [outdated, current]] of Object.entries(playerHighlightCorrections)) {
  const path = join(root, 'content', locale, 'players.json');
  const document = JSON.parse(await readFile(path, 'utf8'));
  document.body = document.body.replace(outdated, current);
  await writeFile(path, `${JSON.stringify(document, null, 4)}\n`);
}

const additions = {
  de: {
    'messages.json': `<h2 id="attachments-and-reach">Anhänge und erreichbare Personen</h2><p>Du kannst bis zu fünf Dateien mit jeweils höchstens 10 MB anhängen. Anhänge bleiben im Posteingang und im Ordner <strong>Gesendet</strong> an der Nachricht verfügbar. Die Personensuche bietet erreichbare Mitglieder und Verantwortliche des eigenen Vereins sowie verbundener Spielgemeinschaften an. Die Bezeichnung unter dem Namen beschreibt den fachlichen Kontext und nicht nur den Besitz eines Benutzerkontos.</p>`,
    'players.json': `<h2 id="linked-account-and-teams">Verknüpftes Konto und Mannschaftszuordnungen</h2><p>Die Detailansicht zeigt die bekannte E-Mail-Adresse des verknüpften Benutzerkontos zusammen mit den übrigen Kontaktdaten. In der Bearbeitung stehen laufende Mannschaftszuordnungen vor beendeten. Prüfe Team, Zuordnungstyp, Trikotnummer sowie Beginn und Ende. Spieler dürfen durch Aufstellung oder Import nicht pauschal der gegnerischen Mannschaft zugeordnet werden.</p>`,
    'calendar.json': `<h2 id="club-visibility-and-training-plans">Vereinssichtbarkeit und Trainingsplanung</h2><p>Bei einem Event bietet <strong>Spezifische Teams</strong> Mannschaften und <strong>Spezifische Vereine</strong> tatsächlich Vereine an. Nach dem Speichern sehen nur die gewählten Zielgruppen den Termin. Bei einem Training führt <strong>Training planen</strong> zur <a href="/de/training-planning">Trainingsplanung</a> des bestehenden Kalendertermins.</p>`,
    'games.json': `<h2 id="abandoned-games-and-comments">Abgebrochene Spiele und Live-Kommentare</h2><p>Ein abgebrochenes Spiel besitzt einen eigenen Status, wird entsprechend gekennzeichnet und nicht wie ein regulär beendetes Spiel in „Mein Verein“-Statistiken gerechnet. Im Live-Ticker kannst du einen eigenständigen Kommentar veröffentlichen, ohne dafür ein Tor, eine Karte oder ein anderes Spielereignis anzulegen.</p>`,
    'quick-events.json': `<h2 id="test-preview">Testvorschau auf kleinen Bildschirmen</h2><p>Die Testansicht verwendet dasselbe Quick-Event-Panel wie am Spieltag. Der kompakte Hinweis kennzeichnet die Generalprobe, ohne die Bedienfläche zu verdecken. Über die Testzeit und Zeitsprünge simulierst du spätere Spielphasen; Verlauf und Funktionsumfang bleiben erhalten. Browserleisten von Safari gehören zum Browser und können je nach Gerät zusätzlich Platz beanspruchen.</p>`,
    'football-de-import.json': `<h2 id="league-cup-and-team-safety">Liga, Pokal und Mannschaftszuordnung prüfen</h2><p>Importierte Spiele verwenden den zentralen sportartenübergreifenden Katalog für Ligen und Pokale. Prüfe in der Importvorschau Sportart, Liga beziehungsweise Pokal, Spieltyp, Ort und Teams. Diese Angaben bleiben auch beim späteren Bearbeiten erhalten. Importierte Spieler können angelegt und dem eigenen eindeutig erkannten Team zugeordnet werden; Kaderblick ordnet sie nicht pauschal dem Gegner zu.</p>`,
    'club-management.json': `<h2 id="current-workspaces">Aktuelle Arbeitsbereiche und zusammenhängende Wege</h2><p>Die Hauptnavigation gliedert die Vereinsverwaltung in <strong>Übersicht</strong>, <strong>Mitglieder</strong>, <strong>Organisation</strong>, <strong>Finanzen &amp; Bank</strong>, <strong>Dokumente &amp; Meldungen</strong>, <strong>Auswertungen</strong> und <strong>Vereinsverwaltung einrichten</strong>. Auf dem Smartphone bleiben sowohl diese Bereichsnavigation als auch die globale untere Navigation erreichbar.</p><ul><li><strong>Mitglieder:</strong> Aufgaben und Anträge bearbeiten, Personen suchen, Mitgliedsakte öffnen, importieren und Datenqualität prüfen.</li><li><strong>Organisation:</strong> Struktur anlegen, Personen zuordnen, Nachweise zu Qualifikationen hinterlegen und Jubiläen vorbereiten.</li><li><strong>Finanzen &amp; Bank:</strong> Beitragsgrundlagen, Vorschau, Freigabe, Forderungen, Zahlungen, Mahnung, SEPA und Bankabgleich in fachlicher Reihenfolge bearbeiten.</li><li><strong>Dokumente &amp; Meldungen:</strong> Archiv, Nachweise, Seriendokumente, Vorlagen und Zustellprobleme verwalten.</li></ul><figure class="screenshot"><img src="/images/docs/de/club-management/organization.png" alt="Organisationsarbeitsbereich der Vereinsverwaltung" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Organisation verbindet Vereinsstruktur, verantwortliche Personen, Ehrungen und Qualifikationen.</figcaption></figure><figure class="screenshot"><img src="/images/docs/de/club-management/documents.png" alt="Dokumentarbeitsbereich der Vereinsverwaltung" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Dokumente und Zustellaufgaben bleiben in einem eigenen Arbeitsbereich.</figcaption></figure>`,
  },
  en: {
    'messages.json': `<h2 id="attachments-and-reach">Attachments and reachable people</h2><p>You can attach up to five files of no more than 10 MB each. Attachments remain available in Inbox and Sent. Person search includes reachable members and responsible people from your club and connected joint teams. The label below a name describes the professional context, not merely that the person has an account.</p>`,
    'players.json': `<h2 id="linked-account-and-teams">Linked account and team assignments</h2><p>Player details show the known email address of the linked account with the other contact data. Current team assignments appear before ended ones. Check team, assignment type, shirt number, start and end. Line-ups and imports must not assign players to the opposing team by default.</p>`,
    'calendar.json': `<h2 id="club-visibility-and-training-plans">Club visibility and training plans</h2><p>For an event, <strong>Specific teams</strong> offers teams and <strong>Specific clubs</strong> offers clubs. Only the selected audiences see the saved event. For a training, <strong>Plan training</strong> opens the <a href="/en/training-planning">training plan</a> for the existing calendar event.</p>`,
    'games.json': `<h2 id="abandoned-games-and-comments">Abandoned matches and live comments</h2><p>An abandoned match has its own status and is not counted as a normally completed match in My club statistics. The live ticker can publish a standalone comment without creating a goal, card or other match event.</p>`,
    'quick-events.json': `<h2 id="test-preview">Test preview on small screens</h2><p>The test view uses the same Quick Event panel as matchday. A compact rehearsal notice does not cover the controls. Test time and jumps simulate later phases while history and functionality remain available. Safari browser bars may use additional screen space depending on the device.</p>`,
    'football-de-import.json': `<h2 id="league-cup-and-team-safety">Check league, cup and team assignment</h2><p>Imported matches use the central cross-sport catalogue for leagues and cups. Review sport, league or cup, match type, venue and teams. These values remain when the match is edited later. Imported players may be created and assigned to their clearly identified own team; they are not assigned to the opponent by default.</p>`,
    'club-management.json': `<h2 id="current-workspaces">Current workspaces and connected workflows</h2><p>Main navigation separates Overview, Members, Organisation, Finance &amp; bank, Documents &amp; reports, Evaluations and Set up club management. On phones, both this area navigation and the global bottom navigation remain available.</p><ul><li><strong>Members:</strong> process tasks and applications, find people, open member records, import and check data quality.</li><li><strong>Organisation:</strong> build structures, assign people, store qualification evidence and prepare anniversaries.</li><li><strong>Finance &amp; bank:</strong> process contribution foundations, previews, approvals, receivables, payments, dunning, SEPA and reconciliation in sequence.</li><li><strong>Documents:</strong> manage archive, evidence, serial documents, templates and delivery issues.</li></ul><figure class="screenshot"><img src="/images/docs/en/club-management/organization.png" alt="Organisation workspace in club management" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Organisation connects structures, responsible people, honours and qualifications.</figcaption></figure><figure class="screenshot"><img src="/images/docs/en/club-management/documents.png" alt="Document workspace in club management" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Documents and delivery tasks remain in a dedicated workspace.</figcaption></figure>`,
  },
  fr: {
    'messages.json': `<h2 id="attachments-and-reach">Pièces jointes et personnes joignables</h2><p>Tu peux joindre jusqu’à cinq fichiers de 10 Mo maximum chacun. Ils restent disponibles dans la réception et les messages envoyés. La recherche propose les membres et responsables joignables du club ainsi que des ententes liées. Le libellé sous le nom décrit le contexte réel, pas seulement l’existence d’un compte.</p>`,
    'players.json': `<h2 id="linked-account-and-teams">Compte lié et affectations d’équipe</h2><p>La fiche affiche l’adresse e-mail connue du compte lié avec les autres contacts. Les affectations en cours précèdent les anciennes. Vérifie équipe, type, numéro, début et fin. Une composition ou un import ne doit pas affecter automatiquement les joueurs à l’adversaire.</p>`,
    'calendar.json': `<h2 id="club-visibility-and-training-plans">Visibilité par club et planification</h2><p><strong>Équipes spécifiques</strong> propose des équipes et <strong>Clubs spécifiques</strong> propose des clubs. Seuls les groupes choisis voient le rendez-vous. Pour un entraînement, <strong>Planifier</strong> ouvre la <a href="/fr/training-planning">planification</a> du rendez-vous existant.</p>`,
    'games.json': `<h2 id="abandoned-games-and-comments">Matchs interrompus et commentaires</h2><p>Un match interrompu possède son propre statut et n’est pas compté comme terminé dans les statistiques du club. Le direct permet de publier un commentaire autonome sans créer de but, carton ou autre événement.</p>`,
    'quick-events.json': `<h2 id="test-preview">Aperçu de test sur petit écran</h2><p>Le test utilise le même panneau que le jour du match. L’avertissement compact de répétition ne masque pas les commandes. L’heure de test et les sauts simulent les phases ultérieures tout en conservant l’historique. Les barres Safari peuvent occuper un espace supplémentaire.</p>`,
    'football-de-import.json': `<h2 id="league-cup-and-team-safety">Contrôler ligue, coupe et équipe</h2><p>Les matchs importés utilisent le catalogue commun des ligues et coupes, avec leur sport. Contrôle sport, ligue ou coupe, type, lieu et équipes. Ces valeurs restent lors d’une modification ultérieure. Un joueur importé peut être créé et affecté à son équipe clairement reconnue, jamais globalement à l’adversaire.</p>`,
    'club-management.json': `<h2 id="current-workspaces">Espaces actuels et processus liés</h2><p>La navigation principale sépare Vue d’ensemble, Membres, Organisation, Finances et banque, Documents et déclarations, Analyses et Configuration. Sur téléphone, cette navigation et la barre globale inférieure restent disponibles.</p><ul><li><strong>Membres :</strong> demandes, personnes, dossiers, import et qualité.</li><li><strong>Organisation :</strong> structures, affectations, justificatifs de qualification et anniversaires.</li><li><strong>Finances et banque :</strong> bases, aperçus, validations, créances, paiements, relances, SEPA et rapprochement.</li><li><strong>Documents :</strong> archives, justificatifs, séries, modèles et problèmes de remise.</li></ul><figure class="screenshot"><img src="/images/docs/fr/club-management/organization.png" alt="Espace Organisation de la gestion du club" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Organisation relie structures, responsables, distinctions et qualifications.</figcaption></figure><figure class="screenshot"><img src="/images/docs/fr/club-management/documents.png" alt="Espace Documents de la gestion du club" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Documents et remises restent dans un espace dédié.</figcaption></figure>`,
  },
  ru: {
    'messages.json': `<h2 id="attachments-and-reach">Вложения и доступные адресаты</h2><p>Можно прикрепить до пяти файлов размером не более 10 МБ каждый. Вложения доступны во входящих и отправленных сообщениях. Поиск показывает доступных участников и ответственных своего клуба и связанных объединённых команд. Подпись описывает рабочий контекст, а не просто наличие аккаунта.</p>`,
    'players.json': `<h2 id="linked-account-and-teams">Связанный аккаунт и команды</h2><p>Карточка показывает известный адрес электронной почты связанного аккаунта вместе с контактами. Текущие назначения команд идут перед завершёнными. Проверь команду, тип, номер, начало и окончание. Состав или импорт не должны автоматически назначать игрока сопернику.</p>`,
    'calendar.json': `<h2 id="club-visibility-and-training-plans">Видимость для клуба и планы тренировок</h2><p><strong>Определённые команды</strong> предлагает команды, а <strong>Определённые клубы</strong> — клубы. Событие видят только выбранные группы. Для тренировки кнопка планирования открывает <a href="/ru/training-planning">план</a> существующего события.</p>`,
    'games.json': `<h2 id="abandoned-games-and-comments">Прерванные матчи и комментарии</h2><p>Прерванный матч имеет отдельный статус и не учитывается как нормально завершённый в статистике клуба. В прямом репортаже можно опубликовать самостоятельный комментарий без гола, карточки или другого события.</p>`,
    'quick-events.json': `<h2 id="test-preview">Тест на небольшом экране</h2><p>Тест использует ту же панель, что и матч. Компактное уведомление о репетиции не перекрывает управление. Тестовое время и переходы моделируют поздние фазы, сохраняя историю и функции. Панели Safari могут занимать дополнительное место.</p>`,
    'football-de-import.json': `<h2 id="league-cup-and-team-safety">Проверить лигу, кубок и команду</h2><p>Импорт использует общий для всех видов спорта каталог лиг и кубков. Проверь вид спорта, лигу или кубок, тип, место и команды. Эти данные сохраняются при дальнейшей правке. Импортированный игрок может быть создан и назначен своей однозначно распознанной команде, но не сопернику по умолчанию.</p>`,
    'club-management.json': `<h2 id="current-workspaces">Актуальные разделы и связанные процессы</h2><p>Навигация разделяет обзор, участников, организацию, финансы и банк, документы и отчётность, аналитику и настройку. На телефоне остаются доступны навигация раздела и глобальная нижняя панель.</p><ul><li><strong>Участники:</strong> заявки, люди, карточки, импорт и качество данных.</li><li><strong>Организация:</strong> структуры, назначения, подтверждения квалификации и юбилеи.</li><li><strong>Финансы и банк:</strong> основы, предварительный просмотр, согласования, начисления, платежи, взыскание, SEPA и сверка.</li><li><strong>Документы:</strong> архив, подтверждения, серии, шаблоны и проблемы доставки.</li></ul><figure class="screenshot"><img src="/images/docs/ru/club-management/organization.png" alt="Раздел организации клуба" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Организация связывает структуру, ответственных, награды и квалификации.</figcaption></figure><figure class="screenshot"><img src="/images/docs/ru/club-management/documents.png" alt="Раздел документов клуба" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">Документы и доставка находятся в отдельном рабочем разделе.</figcaption></figure>`,
  },
  zh_Hans: {
    'messages.json': `<h2 id="attachments-and-reach">附件与可联系人员</h2><p>最多可添加五个附件，每个不超过 10 MB。收件箱和已发送中都能继续查看附件。人员搜索会显示本俱乐部及关联联队中可联系的会员和负责人。姓名下方说明的是实际职责，而不只是“拥有账号”。</p>`,
    'players.json': `<h2 id="linked-account-and-teams">关联账号与球队归属</h2><p>球员详情会与其他联系方式一起显示关联账号的已知邮箱。当前球队归属排在已结束归属之前。请检查球队、类型、号码、开始和结束。阵容或导入不得默认把球员归到对手球队。</p>`,
    'calendar.json': `<h2 id="club-visibility-and-training-plans">俱乐部可见范围与训练计划</h2><p><strong>指定球队</strong>提供球队，<strong>指定俱乐部</strong>提供俱乐部。保存后只有所选对象可见。训练中的计划操作会打开现有日历训练的<a href="/zh-hans/training-planning">训练计划</a>。</p>`,
    'games.json': `<h2 id="abandoned-games-and-comments">中断比赛与直播评论</h2><p>中断的比赛有独立状态，不会在“我的俱乐部”统计中按正常结束计算。直播中可以单独发布评论，无需创建进球、牌或其他比赛事件。</p>`,
    'quick-events.json': `<h2 id="test-preview">小屏幕测试预览</h2><p>测试使用与比赛日相同的快速事件面板。紧凑的演练提示不会遮挡操作。测试时间和跳转可模拟后续阶段，同时保留历史和全部功能。Safari 浏览器栏可能额外占用屏幕空间。</p>`,
    'football-de-import.json': `<h2 id="league-cup-and-team-safety">检查联赛、杯赛和球队归属</h2><p>导入比赛使用跨项目统一的联赛与杯赛目录。请检查运动项目、联赛或杯赛、比赛类型、地点和球队；之后编辑时这些内容仍会保留。导入球员可以创建并归到明确识别的本方球队，不会默认归到对手。</p>`,
    'club-management.json': `<h2 id="current-workspaces">当前工作区与连续流程</h2><p>主导航分为概览、会员、组织、财务与银行、文档与报送、分析以及俱乐部管理设置。手机上区域导航和全局底部导航都保持可用。</p><ul><li><strong>会员：</strong>处理任务和申请、查找人员、打开档案、导入并检查数据质量。</li><li><strong>组织：</strong>建立结构、分配人员、保存资格证明并准备纪念事项。</li><li><strong>财务与银行：</strong>按顺序处理缴费基础、预览、批准、应收、付款、催缴、SEPA 和对账。</li><li><strong>文档：</strong>管理归档、证明、批量文档、模板和送达问题。</li></ul><figure class="screenshot"><img src="/images/docs/zh-hans/club-management/organization.png" alt="俱乐部管理的组织工作区" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">组织工作区连接结构、负责人、荣誉和资格。</figcaption></figure><figure class="screenshot"><img src="/images/docs/zh-hans/club-management/documents.png" alt="俱乐部管理的文档工作区" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">文档与送达任务位于独立工作区。</figcaption></figure>`,
  },
};

for (const [locale, files] of Object.entries(additions)) {
  for (const [filename, addition] of Object.entries(files)) {
    const path = join(root, 'content', locale, filename);
    const document = JSON.parse(await readFile(path, 'utf8'));
    const marker = addition.match(/id="([^"]+)"/)?.[1];
    if (marker && !document.body.includes(`id="${marker}"`)) document.body += addition;
      await writeFile(path, `${JSON.stringify(document, null, 4)}\n`);
  }
}

const adminTerms = {
  de: ['Altersklassen, Wettbewerbe, Positionen', 'Altersklassen, sportartenübergreifende Ligen und Pokale, Positionen'],
  en: ['age groups, competitions, positions', 'age groups, cross-sport leagues and cups, positions'],
  fr: ['catégories d’âge, compétitions, postes', 'catégories d’âge, ligues et coupes multisports, postes'],
  ru: ['возрастные группы, соревнования, позиции', 'возрастные группы, общие для видов спорта лиги и кубки, позиции'],
  zh_Hans: ['年龄组、赛事、位置', '年龄组、跨项目联赛和杯赛、位置'],
};
for (const [locale, [before, after]] of Object.entries(adminTerms)) {
  const path = join(root, 'content', locale, 'admin.json');
  const document = JSON.parse(await readFile(path, 'utf8'));
  document.body = document.body.replace(before, after);
    await writeFile(path, `${JSON.stringify(document, null, 4)}\n`);
}

console.log('November 2026 user documentation updated in all five locales.');
